class Solution {
public:
    long long maxStrength(vector<int>& nums) {
        long long mx = nums[0], mn = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            long long x = nums[i];
            long long a = x, b = mx * x, c = mn * x;
            mx = max({a, b, c});
            mn = min({a, b, c});
        }
        return mx;
    }
};

