class Solution {
    public long maxStrength(int[] nums) {
        long mx = nums[0], mn = nums[0];
        for (int i = 1; i < nums.length; i++) {
            long x = nums[i];
            long a = x, b = mx * x, c = mn * x;
            mx = Math.max(a, Math.max(b, c));
            mn = Math.min(a, Math.min(b, c));
        }
        return mx;
    }
}

