class Solution:
    def maxStrength(self, nums: list[int]) -> int:
        n = len(nums)
        best = float('-inf')
        for mask in range(1, 1 << n):
            p = 1
            for i in range(n):
                if mask >> i & 1: p *= nums[i]
            best = max(best, p)
        return best

